#!/usr/bin/env python3
# generated by GitHub Copilot
import argparse
import re
import subprocess
from pathlib import Path
from urllib.request import urlopen

DEFAULT_TAG_OR_BRANCH = "6.1"
URL_TEMPLATE = "https://raw.githubusercontent.com/zopefoundation/Zope/{tag_or_branch}/constraints.txt"
DEFAULT_PYPROJECT = Path.cwd() / "pyproject.toml"


def build_constraints_url(tag_or_branch: str) -> str:
    return URL_TEMPLATE.format(tag_or_branch=tag_or_branch)


def fetch_constraints(url: str) -> list[str]:
    with urlopen(url) as response:
        text = response.read().decode("utf-8")
    return _clean_lines(text)


def run_uv_pip_freeze() -> list[str]:
    result = subprocess.run(
        ["uv", "pip", "freeze"],
        capture_output=True,
        text=True,
        check=True,
    )
    return _clean_lines(result.stdout)


def normalize_name(raw: str) -> str:
    line = raw.strip().lower()
    if not line:
        return ""

    if " #" in line:
        line = line.split(" #", 1)[0].strip()

    for prefix in ("zope-", "five-", "products-", "plone-", "collective-", "z3c-", "zc-"):
        if line.startswith(prefix):
            return prefix[:-1] + "." + line[len(prefix):]

    return line


def requirement_key(line: str) -> str:
    parts = line.split(";", 1)
    requirement = parts[0].strip()
    marker = parts[1].strip() if len(parts) > 1 else ""

    match = re.match(r"^([a-z0-9._-]+)", requirement)
    if not match:
        return line

    name = match.group(1)
    return f"{name}; {marker}" if marker else name


def format_output_name(line: str) -> str:
    parts = line.split(";", 1)
    requirement = parts[0].strip()
    marker = f"; {parts[1].strip()}" if len(parts) > 1 else ""

    match = re.match(r"^([a-z0-9._-]+)(.*)$", requirement)
    if not match:
        return line

    name = match.group(1).replace(".", "-")
    rest = match.group(2)
    return f"{name}{rest}{marker}"


def _clean_lines(text: str) -> list[str]:
    cleaned = []
    seen = set()

    for raw_line in text.splitlines():
        line = normalize_name(raw_line)

        if not line or line.startswith("#"):
            continue

        if line.startswith(("-e ", "--editable", "-r ", "--requirement", "-")):
            continue

        if line not in seen:
            seen.add(line)
            cleaned.append(line)

    return cleaned


def merged_entries(url: str, include_uv_pip_freeze: bool = True) -> list[str]:
    merged: dict[str, str] = {}

    if include_uv_pip_freeze:
        for item in run_uv_pip_freeze():
            merged[requirement_key(item)] = item

    for item in fetch_constraints(url):
        merged[requirement_key(item)] = item

    return sorted(format_output_name(value) for value in merged.values())


def render_constraint_block(entries: list[str]) -> list[str]:
    lines = ["constraint-dependencies = ["]
    for entry in entries:
        lines.append(f'    "{entry}",')
    lines.append("]")
    return lines


def rebuild_tool_uv_section(old_section: str, entries: list[str]) -> str:
    lines = old_section.splitlines()
    preserved = []
    in_constraint = False
    bracket_depth = 0

    for line in lines:
        stripped = line.strip()

        if stripped.startswith("constraint-dependencies"):
            in_constraint = True
            if "[" in line:
                bracket_depth += line.count("[")
            if "]" in line:
                bracket_depth -= line.count("]")
            if bracket_depth <= 0:
                in_constraint = False
            continue

        if in_constraint:
            if "[" in line:
                bracket_depth += line.count("[")
            if "]" in line:
                bracket_depth -= line.count("]")
            if bracket_depth <= 0:
                in_constraint = False
            continue

        preserved.append(line)

    # Remove trailing empty lines from preserved content.
    while preserved and preserved[-1].strip() == "":
        preserved.pop()

    result = preserved[:]

    # Ensure exactly one blank line before the new constraint block.
    if result:
        result.append("")

    result.extend(render_constraint_block(entries))
    return "\n".join(result).rstrip() + "\n"


def update_pyproject(path: Path, entries: list[str]) -> None:
    if path.exists():
        text = path.read_text(encoding="utf-8")
    else:
        text = ""

    section_pattern = re.compile(r"(?ms)^\[tool\.uv\]\n.*?(?=^\[|\Z)")
    match = section_pattern.search(text)

    if match:
        new_section = rebuild_tool_uv_section(match.group(0), entries)
        text = text[: match.start()] + new_section + text[match.end() :]
    else:
        if text and not text.endswith("\n"):
            text += "\n"
        if text:
            text += "\n"
        text += "[tool.uv]\n"
        text += "\n".join(render_constraint_block(entries)) + "\n"

    path.write_text(text, encoding="utf-8")


def main() -> int:
    parser = argparse.ArgumentParser(
        description="Refresh [tool.uv].constraint-dependencies in pyproject.toml"
    )
    parser.add_argument(
        "--version",
        default=DEFAULT_TAG_OR_BRANCH,
        help=f"Zope tag or branch used to build the constraints URL (default: {DEFAULT_TAG_OR_BRANCH})",
    )
    parser.add_argument(
        "--ignore-uv-pip-freeze",
        action="store_true",
        help="Ignore entries from 'uv pip freeze' and use only the remote constraints file.",
    )
    args = parser.parse_args()

    url = build_constraints_url(args.version)
    entries = merged_entries(url, include_uv_pip_freeze=not args.ignore_uv_pip_freeze)
    update_pyproject(DEFAULT_PYPROJECT, entries)
    print(f"Updated {DEFAULT_PYPROJECT}")
    print(f"Used constraints from {url}")
    if args.ignore_uv_pip_freeze:
        print("Ignored entries from uv pip freeze")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
